import{_ as a,C as i,o as n,c as r,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Evidence: Cancellation Boundaries and Artifact Continuity","description":"","frontmatter":{"title":"Evidence: Cancellation Boundaries and Artifact Continuity","outline":"deep"},"headers":[],"relativePath":"en/research/evidence/2026-09-06-execution-artifact-continuity.md","filePath":"en/research/evidence/2026-09-06-execution-artifact-continuity.md","lastUpdated":1788751356000}'),c={name:"en/research/evidence/2026-09-06-execution-artifact-continuity.md"};function l(d,e,h,u,p,f){const t=i("ArticleTableScroll");return n(),r("div",null,[o(t,{language:"en"}),e[0]||(e[0]=s('<h1 id="evidence-cancellation-boundaries-and-artifact-continuity" tabindex="-1">Evidence: cancellation boundaries and artifact continuity <a class="header-anchor" href="#evidence-cancellation-boundaries-and-artifact-continuity" aria-label="Permalink to &quot;Evidence: cancellation boundaries and artifact continuity&quot;">​</a></h1><p>Publication of this bilingual study and evidence was authorized on 2026-09-07. The experiments ran on 2026-09-06 at CodeFlowMu baseline <code>c008d9db91a21136fc61a4f60314e22db395d5d2</code>. This is not security certification, independent QA, or development authorization.</p><p><a href="/joinwell52/zh/research/evidence/2026-09-06-execution-artifact-continuity">中文</a> · <a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/execution-artifact-evidence.zip" target="_blank" rel="noreferrer">Download full evidence ZIP</a> · <a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/evidence/README.en.md" target="_blank" rel="noreferrer">Full English guide</a></p><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li><a href="/joinwell52/en/engineering/2026-09-06-cancellation-execution-boundary">You Clicked Cancel. Which Step Did It Actually Cancel?</a></li><li><a href="/joinwell52/en/engineering/2026-09-06-workspace-artifact-continuity">The File Was Written Successfully. Why Check the Artifact Again?</a></li></ul><h2 id="claim-mapping" tabindex="-1">Claim mapping <a class="header-anchor" href="#claim-mapping" aria-label="Permalink to &quot;Claim mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Records</th><th>Observations</th><th>Required qualification</th></tr></thead><tbody><tr><td>A0–A3</td><td>Replay rejected; pending request enters cancelled or expired state; approved execution at second 31</td><td>The 30-second deadline governs review; A1 rejects an unissued credential, not an already approved token being revoked</td></tr><tr><td>A4–A6</td><td>Cancellation rejected while waiting; a research abort check prevents writing; an existing effect remains</td><td>Not successful revocation followed by execution; the barrier is injected</td></tr><tr><td>Three adapter scenarios</td><td>Per round: one normal reply, zero replies in either cancellation case</td><td>Real local adapter with fake process transport; not a real host&#39;s post-lock check</td></tr><tr><td>B0–B3</td><td>Stable same-request digest; changed target rejects old approval; another workspace or task changes operation digest</td><td>B2/B3 verify digest distinction; B1 additionally verifies execution rejection, not acceptance of every cross-workspace or cross-task path</td></tr><tr><td>B4</td><td>New-process digest matches; historical success coexists with original-path absence after rename</td><td>Three points for one file; no deletion, power loss, or business acceptance</td></tr></tbody></table><p>Twelve service/workspace scenarios and three adapter scenarios each ran twice: 30 observations, not 30 distinct scenarios or an accuracy score. The baseline test set, comprising two existing test files, ran twice, with a total of 39 pass / 0 fail / 0 skip per round. Both original baseline logs are retained in redacted form.</p><p>The editorial revision on 2026-09-07 only refines these claim boundaries. Original observations, figures, probes, the download archive, and their hashes remain unchanged; no new experiment was added.</p><h2 id="verification-and-rerunning" tabindex="-1">Verification and rerunning <a class="header-anchor" href="#verification-and-rerunning" aria-label="Permalink to &quot;Verification and rerunning&quot;">​</a></h2><p>Extract the complete ZIP, enter evidence, and run <code>node check.mjs</code>. It checks the 30 exported observations, two baseline logs, and file hashes. It verifies existing records rather than rerunning the product.</p><p><code>probe-boundaries.mjs</code> and <code>probe-adapter.mjs</code> are configurable copies of the executed research scripts. Hardcoded source paths become <code>CODEFLOWMU_SOURCE_ROOT</code>; the adapter creates its fixture directory for standalone use. Execution still requires authorized access to the fixed CodeFlowMu source, dependencies, and a TypeScript loader. See the bilingual guide. Product source, real tokens, and operational ledgers are not distributed. Readers without source access can check public records but cannot claim a product rerun.</p><h2 id="integrity-and-redaction" tabindex="-1">Integrity and redaction <a class="header-anchor" href="#integrity-and-redaction" aria-label="Permalink to &quot;Integrity and redaction&quot;">​</a></h2><p>All scenarios, rounds, outcomes, error codes, and effect counts are retained. Machine paths and child PIDs are removed. Original-record hashes and before/after checks for seven product source files are in provenance.json. Hashes identify records and detect changes relative to the manifest; they are not independent signatures or correctness proofs.</p><p>The normal adapter scenario ends in cancelled only during cleanup; kill_calls counts fake-process calls. B1&#39;s intervening bytes and B4&#39;s preserved bytes were reread during editorial review without inventing new original-observation fields. Raw local fixtures and operational configuration are withheld.</p><p>OpenHands #4866 and Paperclip #12901 versions/statuses are study-date snapshots. Neither upstream experiments nor the paid Daytona suite were independently rerun. Publication adds no real-host, authorization-revocation, remote-sync, power-loss, or PM/QA acceptance experiment.</p><h2 id="individual-files" tabindex="-1">Individual files <a class="header-anchor" href="#individual-files" aria-label="Permalink to &quot;Individual files&quot;">​</a></h2><ul><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/evidence/observations.json" target="_blank" rel="noreferrer">observations.json</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/evidence/provenance.json" target="_blank" rel="noreferrer">provenance.json</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/evidence/baseline-1.log" target="_blank" rel="noreferrer">Baseline round 1</a> · <a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/evidence/baseline-2.log" target="_blank" rel="noreferrer">Round 2</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/evidence/check.mjs" target="_blank" rel="noreferrer">Checker</a> · <a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/evidence/manifest.json" target="_blank" rel="noreferrer">Manifest</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/evidence/probe-boundaries.mjs" target="_blank" rel="noreferrer">Approval/workspace probe</a> · <a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/evidence/probe-adapter.mjs" target="_blank" rel="noreferrer">Adapter probe</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/evidence/README.zh.md" target="_blank" rel="noreferrer">README 中文</a> · <a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/evidence/README.en.md" target="_blank" rel="noreferrer">README English</a></li></ul>',18))])}const v=a(c,[["render",l]]);export{g as __pageData,v as default};
